#include <iostream>
using namespace std;

//Used so as to avoid writing same code for different datatypes

//Templates - here the fn or class for different datatypes is generated by the compiler at compile time

template <typename T1> //here T1 is the datatype

T1 find(T1 ele1, T1 ele2){
    return ele1 > ele2? ele1:ele2;
}


//You can also have a template for two diff. dtypes 
template <typename T1, typename T2>  //timepass code

T1 tp(T1 ele1, T2 ele2){
    cout<<ele2<<"\n";
    return ele1;
}


template <typename T1> 

T1 max_in_arr(T1 arr[], int n){
    T1 temp = arr[0];
    for(int i = 0; i < n; i++){
        if(arr[i] < temp)
            temp = arr[i];
    }

    return temp;
}

//Interesting fact, you can also pass some parameters with dtypes in templates

//For ex lets say you don't want to run the above fn for an array having size greater than some threshold

template <typename T1, int thres>  

T1 max_in_arr_2(T1 arr[], int n){   //Note: While calling the below fn, you must provide a const. value for thres
    if(n > thres)
        cout<<"\nVery large size";
    
    else{
        T1 temp = arr[0];
        for(int i = 0; i < n; i++){
            if(arr[i] < temp)
                temp = arr[i];
        }

        return temp;
    }

}




int main(){
    cout<<find<int>(25,27)<<"\n";
    cout<<find<char>('a','z')<<"\n";

    cout<<tp<char,int>('a',81);

    int arr1[] = {7,2,4,5};
    cout<<"\n"<<max_in_arr<int>(arr1,4);

    char arr2[] = {'q','x','y','m'};
    cout<<"\n"<<max_in_arr<char>(arr2,4);

    cout<<"\n"<<max_in_arr_2<int,3>(arr1,4); 

    // int x = 2;
    // cout<<"\n"<<max_in_arr_2<int,x>(arr1,4);  

    //We can't pass variables for thres, because these fns are genrated at compile time.

    const int x = 2;
    cout<<"\n"<<max_in_arr_2<int,x>(arr1,4); //But this will work , because we are passing a constant 


    return 0;
}